package com.gk.jobhelper.service;
import com.gk.jobhelper.common.*;import com.gk.jobhelper.entity.*;import com.gk.jobhelper.mapper.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class CareerFactService {private final CareerFactMapper facts;private final UserProfileMapper profiles;private final RecruitmentQualificationMatchService matches;public CareerFactService(CareerFactMapper f,UserProfileMapper p,RecruitmentQualificationMatchService m){facts=f;profiles=p;matches=m;}public List<CareerFact> list(){return facts.selectByProfileId(profile().getId());}public CareerFact save(CareerFact f){if(f==null||TextNormalizer.isBlank(f.getFactType())||TextNormalizer.isBlank(f.getFactKey())||TextNormalizer.isBlank(f.getValueType()))throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"职业事实类型和值不能为空");if("BOOLEAN".equals(f.getValueType())&&f.getBooleanValue()==null)throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"请明确选择有或没有");if("NUMBER".equals(f.getValueType())&&(f.getNumberValue()==null||f.getNumberValue()<0))throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"请填写有效数值");LocalDateTime now=LocalDateTime.now();f.setProfileId(profile().getId());f.setFactKey(f.getFactKey().trim().toUpperCase(Locale.ROOT));f.setSource("USER_CONFIRMED");f.setConfirmedAt(now);f.setCreatedAt(now);f.setUpdatedAt(now);facts.upsert(f);CareerFact saved=facts.selectByProfileAndKey(f.getProfileId(),f.getFactType(),f.getFactKey());matches.rebuild();return saved;}public void delete(Long id){facts.deleteByIdAndProfile(id,profile().getId());matches.rebuild();}private UserProfile profile(){UserProfile p=profiles.selectFirstProfile();if(p==null)throw new BusinessException(ApiResponse.CODE_PROFILE_NOT_FOUND,"请先保存我的档案。");return p;}}
